mapper.insert:
insert into biz_medical_query_batch_item (
    batch_id, request_id, row_no, reused_flag, item_status, create_time, update_time
) values (
    #{batchId}, #{requestId}, #{rowNo}, #{reusedFlag}, #{itemStatus}, sysdate(), sysdate()
)

mapper.select:
select summary.*
from () summary

    summary.batch_no like concat('%', #{batchNo}, '%')
    and summary.company_name like concat('%', #{companyName}, '%')
    and summary.batch_status = #{batchStatus}
    and summary.create_time >= #{params.beginTime}
    and summary.create_time <= #{params.endTime}

order by summary.create_time desc, summary.id desc

select summary.*
from () summary
where summary.id = #{id}

select *
from biz_medical_query_batch
where company_id = #{companyId}
  and batch_no = #{batchNo}
for update

select *
from biz_medical_query_batch
where company_id = #{companyId}
  and batch_no = #{batchNo}
  and service_mode = 'DELAYED'
